// PRD P8.12–P8.15 — the fee schedule. One pure function shared by the web app and the MCP
// (mcp/src/shared/fee.ts is a generated copy). Jupiter allows 50–255 bps.

export interface FeeSchedule {
  standardBps: number
  sizeBps: number
  sizeThresholdUsd: number
  stakerDiscountBps: number
  /** POT that must be staked for the discount; null until TGE (discount disabled). */
  stakerMinPot: number | null
}

export const JUP_MIN_BPS = 50
export const JUP_MAX_BPS = 255

export const DEFAULT_FEE_SCHEDULE: FeeSchedule = {
  standardBps: 250,
  sizeBps: 100,
  sizeThresholdUsd: 1000,
  stakerDiscountBps: 100,
  stakerMinPot: null,
}

export type FeeTier = 'standard' | 'size' | 'staker'

export interface FeeDecision { bps: number; tier: FeeTier; label: string }

const clamp = (bps: number) => Math.min(JUP_MAX_BPS, Math.max(JUP_MIN_BPS, Math.round(bps)))

/**
 * @param inputUsd USD value of the input amount at quote time; undefined when no price is known (→ standard tier)
 * @param stakedPot POT staked by the wallet; 0 / undefined when unknown
 */
export function feeBpsFor(schedule: FeeSchedule, inputUsd?: number, stakedPot = 0): FeeDecision {
  const size = inputUsd !== undefined && inputUsd >= schedule.sizeThresholdUsd
  let bps = size ? schedule.sizeBps : schedule.standardBps
  let tier: FeeTier = size ? 'size' : 'standard'
  if (schedule.stakerMinPot !== null && stakedPot >= schedule.stakerMinPot) {
    bps -= schedule.stakerDiscountBps
    tier = 'staker'
  }
  bps = clamp(bps)
  const pct = `${bps / 100}%`
  const label = tier === 'standard' ? pct : tier === 'size' ? `${pct} (size tier)` : `${pct} (staker)`
  return { bps, tier, label }
}

/** Parses the schedule from /api/config, falling back to defaults field by field. */
export function parseFeeSchedule(raw: unknown): FeeSchedule {
  const r = (raw ?? {}) as Partial<Record<keyof FeeSchedule, unknown>>
  const num = (v: unknown, d: number) => (typeof v === 'number' && Number.isFinite(v) ? v : d)
  return {
    standardBps: clamp(num(r.standardBps, DEFAULT_FEE_SCHEDULE.standardBps)),
    sizeBps: clamp(num(r.sizeBps, DEFAULT_FEE_SCHEDULE.sizeBps)),
    sizeThresholdUsd: num(r.sizeThresholdUsd, DEFAULT_FEE_SCHEDULE.sizeThresholdUsd),
    stakerDiscountBps: num(r.stakerDiscountBps, DEFAULT_FEE_SCHEDULE.stakerDiscountBps),
    stakerMinPot: typeof r.stakerMinPot === 'number' && r.stakerMinPot > 0 ? r.stakerMinPot : null,
  }
}
